// Scans terminal tasks in a fixed [window_start, window_end] slice that still
// lack a chat_done/task_failed queue row. Stable sort supports page iteration.
func (q *Queries) ListWecomOutboundReconcileCandidates(ctx context.Context, arg ListWecomOutboundReconcileCandidatesParams) ([]ListWecomOutboundReconcileCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listWecomOutboundReconcileCandidates,
		arg.WindowStart,
		arg.WindowEnd,
		arg.AfterCompletedAt,
		arg.AfterTaskID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWecomOutboundReconcileCandidatesRow{}
	for rows.Next() {
		var i ListWecomOutboundReconcileCandidatesRow
		if err := rows.Scan(
			&i.TaskID,
			&i.ChatSessionID,
			&i.TaskStatus,
			&i.CompletedAt,
			&i.FailureReason,
			&i.InstallationID,
			&i.WorkspaceID,
			&i.ChannelType,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

